const storage={get(key,fallback){try{return JSON.parse(localStorage.getItem(`xinworld.prototype.${key}`))??fallback}catch{return fallback}},set(key,v){try{localStorage.setItem(`xinworld.prototype.${key}`,JSON.stringify(v));return true}catch{return false}}};
