const assets=[{id:'a1',title:'向新而行 · 品牌叙事',img:'horizon.png',type:'成果',kind:'品牌文稿',status:'待完善',project:'向新而行',date:'今天 10:24'},{id:'a2',title:'留白之间 · 视觉方向',img:'architecture.svg',type:'成果',kind:'创意提案',status:'已保存',project:'留白之间',date:'今天 09:42'},{id:'a3',title:'慢生活 · 系列内容企划',img:'editorial.svg',type:'成果',kind:'内容企划',status:'已保存',project:'慢生活',date:'昨天 18:30'},{id:'a4',title:'AI 创作趋势 · 研究笔记',img:'research.svg',type:'成果',kind:'研究笔记',status:'已保存',project:'趋势观察',date:'昨天 16:08'},{id:'a5',title:'品牌视觉参考 · 地平线',img:'horizon.png',type:'资料',kind:'图片参考',status:'已保存',project:'向新而行',date:'今天 10:02'},{id:'a6',title:'空间素材 · 光影与结构',img:'architecture.svg',type:'资料',kind:'视觉资料',status:'已保存',project:'留白之间',date:'今天 09:10'},{id:'a7',title:'生活方式访谈 · 原始记录',img:'editorial.svg',type:'资料',kind:'文本资料',status:'已保存',project:'慢生活',date:'昨天 17:20'},{id:'a8',title:'趋势观察 · 资料摘录',img:'research.svg',type:'资料',kind:'文本资料',status:'已保存',project:'趋势观察',date:'昨天 15:00'}];
const state={page:'home',tab:'全部',search:'',status:'全部状态',view:'grid',favorites:storage.get('favorites',[]),panel:'chat',skills:[],messages:[],project:storage.get('project','向新而行 · 品牌企划'),customProjects:storage.get('projects',[]),attachments:[],draft:storage.get('draft',''),saved:storage.get('saved',false)};
const btn=(label,action,ico='',klass='')=>`<button class="btn ${klass}" data-action="${action}">${ico?icon(ico):''}${label}</button>`;
const footer=()=>'<footer class="page-footer"><span>鑫世界 XIN WORLD · 让想法，成为作品。</span><span>交互原型 · 示例数据 / 非生产环境　 <a href="DESIGN-SPEC.md" target="_blank">设计规范 ↗</a>　<a href="AUDIT-REPORT.md" target="_blank">改造报告 ↗</a></span></footer>';
function shell(){const links=[['home','home','首页'],['studio','spark','AI 创作'],['content','grid','内容中心'],['research','book','研究'],['analytics','list','数据中台']];return `<aside class="rail" aria-label="应用导航"><a href="#home" class="brand-mark" aria-label="鑫世界首页">${mark()}</a><nav>${links.map(([p,i,t])=>`<a href="#${p}" class="nav-item ${(state.page===p||(p==='research'&&state.page==='teardown'))?'active':''}" title="${t}" aria-label="${t}" ${state.page===p?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${t}</span></a>`).join('')}<button title="搜索项目与内容" aria-label="搜索项目与内容" data-action="search">${icon('search')}</button></nav><div class="rail-bottom"><button title="使用说明" aria-label="使用说明" data-action="help">${icon('help')}</button><button title="设置与服务" aria-label="设置与服务" data-action="open-settings">${icon('settings')}</button><button title="本地演示账户" aria-label="本地演示账户" data-action="account"><span class="avatar">X</span></button></div></aside><div class="shell"><header class="topbar"><a href="#home" class="brand-name">鑫世界 <small>XIN WORLD / CREATIVE WORKSPACE</small></a><div class="top-actions"><span class="top-note">DUAL EXPERIENCE · 01</span><div class="theme-switch" role="group" aria-label="主题切换"><button data-theme-choice="dark" aria-pressed="${theme()==='dark'}">${icon('moon')}Dark Studio</button><button data-theme-choice="light" aria-pressed="${theme()==='light'}">${icon('sun')}Light Edition</button></div><button class="icon-btn" data-action="notifications" title="消息" aria-label="消息">${icon('bell')}</button></div></header><main id="main" tabindex="-1">${renderPage()}</main></div>`}
const pageRenderers={home,studio,content,teardown:()=>renderTeardown({icon,footer,esc,modal,toast}),capabilities:()=>renderCapabilities({icon,footer,esc,modal,toast}),settings:()=>renderSettings({icon,footer,esc,modal,toast}),research:()=>renderResearch({icon,footer,esc,modal,toast}),analytics:()=>renderAnalytics({icon,footer,esc,modal,toast,detail})};
function renderPage(){return (pageRenderers[state.page]||home)()}
const theme=()=>document.documentElement.dataset.theme;
function card(p,isAsset=false){const fav=state.favorites.includes(p.id);return `<article class="project-card"><button class="card-star" data-favorite="${p.id}" aria-label="收藏${esc(p.title)}" aria-pressed="${fav}" title="收藏">${icon('star')}</button><a class="cover-link" ${isAsset?`href="#content" data-detail="${p.id}"`:'href="#studio" data-project="'+esc(p.title)+'"'} aria-label="打开${esc(p.title)}"><img src="assets/${p.img}" alt="${esc(p.title)}的${p.img.endsWith('.svg')?'矢量视觉封面':'品牌地平线视觉'}" ${isAsset?'loading="lazy"':''}><span class="cover-label">${isAsset?p.kind:p.label}</span></a><div class="card-body"><h3><a ${isAsset?`href="#content" data-detail="${p.id}"`:'href="#studio" data-project="'+esc(p.title)+'"'}>${esc(p.title)}</a></h3><div class="card-meta"><span>${isAsset?p.project:p.type}</span><span>${isAsset?p.date:p.date+'更新'}</span></div><div class="card-foot"><span>${isAsset?p.type:p.count+' 个成果'}</span><span class="badge ${p.status==='待完善'?'orange':p.status==='已完成'||p.status==='已保存'?'green':''}">${p.status}</span></div></div></article>`}
function home(){return `<div class="page home"><section class="hero"><div class="hero-copy"><div class="eyebrow"><i class="red-dot"></i> A NEW HORIZON FOR YOUR IDEAS</div><h1>好想法，<br>值得一个新世界。</h1><p>从第一点灵感，到下一件作品。<br>与 AI 持续协作，让每一次创作都有迹可循。</p><div class="hero-buttons">${btn('开启新项目','new','plus','primary')}<a class="btn" href="#studio">继续上次创作 ${icon('arrow')}</a></div></div><div class="hero-art"><img src="assets/horizon.png" alt="银色水平环与红色圆点构成的地平线艺术装置"></div><span class="hero-caption">XIN WORLD — BEYOND THE HORIZON</span></section><div class="start-strip"><div class="start-copy"><strong>今天，想把什么变成现实？</strong><p>一个项目，连接对话、资料与成果。</p></div><div class="quick-actions">${btn('开始对话','start','spark')}${btn('带着资料开始','import','clip')}<a class="btn" href="#content">${icon('grid')}浏览我的内容</a></div></div><section class="section"><div class="section-heading"><h2>回到你的创作 <span>RECENT PROJECTS</span></h2><button class="text-link icon-btn" style="width:auto" data-action="projects">查看全部 ${icon('arrow')}</button></div><div class="project-grid">${[...state.customProjects,...projects].slice(0,4).map(p=>card(p)).join('')}</div></section><section class="section showcase"><div class="showcase-image"><img src="assets/architecture.svg" alt="留白之间：暖灰色拱门与光影的矢量空间作品"></div><div class="showcase-copy"><div class="eyebrow"><i class="red-dot"></i> MADE WITH XIN WORLD</div><h2>从灵感的一瞬，<br>到作品的每一面。</h2><p>资料成为线索，对话打开思路。<br>将值得留下的想法，沉淀为可以继续打磨的成果。</p><a class="text-link" href="#content">发现你的成果 ${icon('arrow')}</a></div></section>${footer()}</div>`}
function content(){return `<div class="page content"><div class="page-heading"><div><div class="eyebrow" style="margin-bottom:10px">YOUR CREATIVE LIBRARY</div><h1>内容中心</h1><p>每一份资料，每一个成果，都有自己的位置。</p></div>${btn('导入资料','import','upload','primary')}</div><section class="content-banner"><img src="assets/horizon.png" alt="品牌地平线视觉"><div class="banner-copy"><div class="eyebrow">FEATURED PROJECT / 01</div><h2>向新而行。</h2><p>在熟悉的世界里，创造一种新的可能。</p><a href="#studio" class="badge">品牌企划　 ·　 8 个成果　 ${icon('arrow')}</a></div></section><div class="toolbar"><div class="tabs" role="group" aria-label="内容类型">${['全部','成果','资料','收藏'].map(t=>`<button data-tab="${t}" aria-pressed="${state.tab===t}">${t}<small>${t==='全部'?assets.length:t==='收藏'?assets.filter(a=>state.favorites.includes(a.id)).length:assets.filter(a=>a.type===t).length}</small></button>`).join('')}</div><div class="toolbar-right"><label class="searchbox">${icon('search')}<input id="content-search" type="search" placeholder="搜索名称、项目…" aria-label="搜索内容" value="${esc(state.search)}"></label><div class="view-toggle" role="group" aria-label="内容视图"><button class="icon-btn" data-view="grid" aria-label="网格视图" aria-pressed="${state.view==='grid'}">${icon('grid')}</button><button class="icon-btn" data-view="list" aria-label="列表视图" aria-pressed="${state.view==='list'}">${icon('list')}</button></div></div></div><div class="filter-line"><span id="result-count"></span><label>状态　<select id="status-filter" aria-label="筛选状态">${['全部状态','已保存','待完善'].map(x=>`<option ${state.status===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="asset-grid ${state.view==='list'?'list':''}" id="assets"></div>${footer()}</div>`}
function filterAssets(){if(!document.querySelector('#assets'))return;const list=assets.filter(a=>(state.tab==='全部'||state.tab==='收藏'&&state.favorites.includes(a.id)||a.type===state.tab)&&(state.status==='全部状态'||a.status===state.status)&&`${a.title} ${a.project}`.toLowerCase().includes(state.search.toLowerCase()));document.querySelector('#assets').innerHTML=list.length?list.map(a=>card(a,true)).join(''):'<div class="empty"><p>还没有符合条件的内容</p><button class="btn" data-action="clear-filter" style="margin-top:15px">清除筛选</button></div>';document.querySelector('#result-count').textContent=`${list.length} 项内容　 /　 当前工作空间 · 示例数据`}
const defaultDoc=`<div class="document-eyebrow">BRAND NARRATIVE / CREATIVE DRAFT</div><h2>向新而行。<br>让每一个好想法，都有回响。</h2><div class="document-meta">品牌叙事　 ·　 初稿 v1　 ·　 AI 辅助创作 / 示例</div><div id="editable" contenteditable="true" role="textbox" aria-label="编辑品牌叙事" aria-multiline="true"><h3>01 / 我们相信，创造源于看见</h3><p>世界从不缺少可能，缺少的是一次新的看见。<br>在日常的缝隙里，在尚未说出口的想法里，总有一个值得出发的方向。</p><blockquote>让想法越过地平线，<br>让创作抵达新的世界。</blockquote><h3>02 / 让灵感，成为可以继续的工作</h3><p>一个项目，保存每一次探索。资料带来依据，对话打开思路，成果让灵感有了形状。今天的第一稿，成为明天更好的开始。</p><h3>03 / 向新而行，与你一起</h3><p>鑫世界，是你与 AI 持续协作的地方。<br>从一个问题出发，把每一个值得留下的想法，变成属于你的作品。</p><div class="doc-callout">创意说明：红色圆点代表灵感的起点，水平弧线延伸为探索的地平线。此处为品牌叙事演示文案，事实与表述仍需人工核对。</div></div>`;
const userMsg=text=>`<article class="message user"><div class="message-label"><span class="avatar">X</span>你</div><p>${esc(text)}</p></article>`;
const aiMsg=text=>`<article class="message ai"><div class="message-label">${mark()}鑫小助 <span class="badge">演示</span></div><p>${esc(text)}</p></article>`;
function studio(){return `<div class="page studio" data-panel="${state.panel}"><div class="breadcrumb"><a href="#home">我的项目</a>${icon('chevron')}<span>项目工作区</span></div><div class="page-heading"><div class="studio-title"><h1>${esc(state.project)}</h1><span class="badge">进行中</span></div><div>${btn('保存成果','save','check','primary')}</div></div><div class="mobile-workspace-tabs" role="group" aria-label="工作区面板"><button class="btn" data-panel="chat" aria-pressed="${state.panel==='chat'}">${icon('spark')}AI 对话</button><button class="btn" data-panel="document" aria-pressed="${state.panel==='document'}">${icon('file')}成果编辑</button></div><div class="workspace"><aside class="project-panel" aria-label="项目上下文"><div class="panel-label">PROJECT SPACE <span class="red-dot"></span></div><div class="project-name">${icon('folder')}　向新而行</div><div class="tree-heading">对话 <span>01</span></div><button class="tree-row active" data-action="focus-chat">${icon('spark')}品牌叙事探索</button><div class="tree-heading">资料 <button class="icon-btn" style="width:18px;height:18px" data-action="attach" aria-label="附加资料">${icon('plus')}</button></div><button class="tree-row" data-action="brief">${icon('file')}品牌背景与目标<small>TXT</small></button><button class="tree-row" data-detail="a5">${icon('image')}视觉方向参考<small>IMG</small></button><div id="attachments">${attachmentRows()}</div><div class="tree-heading">成果 <span>01</span></div><button class="tree-row active" data-action="focus-doc">${icon('file')}品牌叙事 · 初稿</button><div class="tree-heading">可选技能 <span id="skill-count">${state.skills.length}</span></div><button class="skill-chip" data-backend="skills">${icon('spark')}<span id="skill-label">${state.skills.length?'品牌叙事 · 已启用':'添加专业技能'}</span></button><p class="skill-note">按需添加，也可以直接开始。<br>通用 AI 无需预选技能。</p><div class="project-progress">项目上下文<div><i></i></div>2 份参考资料 · 1 个成果</div></aside><section class="chat-panel" aria-label="AI 对话"><div class="panel-top"><strong>${icon('spark')}　与鑫小助协作</strong><small>示例对话</small></div><div class="chat-thread" id="chat-thread"><div class="chat-date">今天　10:24 / 持续协作</div>${userMsg('结合品牌资料，帮我写一版「向新而行」的品牌叙事。希望简洁、有力量，也保留一点温度。')}<article class="message ai"><div class="message-label">${mark()}鑫小助 <span class="badge">演示</span></div><div class="thinking">${icon('check')}已参考 2 份项目资料</div><p>我会围绕「看见可能 → 持续探索 → 形成作品」展开，让叙事与你的品牌视觉保持一致。</p><span class="source-pill">${icon('clip')}品牌背景与目标</span> <span class="source-pill">${icon('image')}视觉方向参考</span><p style="margin-top:16px">第一版已放到右侧成果区。可以直接编辑，也可以继续告诉我你想调整的方向。</p><button class="artifact-reply" data-action="focus-doc">${icon('file')}<span><strong>向新而行 · 品牌叙事</strong><small>可编辑成果　 /　 初稿 v1</small></span>${icon('arrow').replace('<svg','<svg class="arrow"')}</button><div class="suggestions"><button data-prompt="让开头更有力量">让开头更有力量</button><button data-prompt="精简为 100 字品牌介绍">精简为 100 字</button><button data-prompt="提供 3 个标题方向">探索标题方向</button></div></article>${state.messages.map(m=>m.role==='user'?userMsg(m.text):aiMsg(m.text)).join('')}</div><form class="composer" id="chat-form"><textarea id="prompt" placeholder="继续聊聊你的想法，或让 AI 修改这份成果…" aria-label="向 AI 发送消息">${esc(state.draft)}</textarea><div id="chat-attachments" style="font-size:9px;color:var(--quiet)">${state.attachments.map(a=>esc(a)).join(' · ')}</div><div class="composer-tools"><div><button type="button" class="icon-btn" style="width:27px;height:27px" data-action="attach" aria-label="附加本地资料">${icon('clip')}</button><select id="model" aria-label="选择演示模型"><option>通用 AI · 演示</option><option>深度思考 · 演示</option></select></div><button class="send" type="submit" aria-label="发送消息">${icon('send')}</button></div></form><p class="composer-note">演示回复 · 未连接 AI 服务 · 请核对生成内容</p></section><section class="document-panel" aria-label="成果编辑器"><div class="panel-top"><strong>${icon('file')}　品牌叙事 · 初稿</strong><button class="icon-btn" data-action="export" aria-label="导出成果" title="导出文本">${icon('download')}</button></div><div class="document-toolbar"><span style="margin:0">可编辑文稿</span><button class="icon-btn" data-action="font-smaller" aria-label="缩小文稿字号">A−</button><button class="icon-btn" data-action="font-larger" aria-label="放大文稿字号">A+</button><span id="save-status">${state.saved?'已保存到此浏览器':'尚未保存修改'}</span></div><article class="document-sheet" id="document-sheet">${defaultDoc}</article><div class="document-bottom"><span id="word-count"></span><span>文本成果　 /　 本地原型</span></div></section></div>${footer()}</div>`}
function attachmentRows(){return state.attachments.map(a=>`<div class="tree-row">${icon('clip')}<span style="overflow:hidden;text-overflow:ellipsis">${esc(a)}</span></div>`).join('')}
let docCache=storage.get('document',null),toastTimer,working=false;
function render(){captureDoc();document.querySelector('#app').innerHTML=shell();if(state.page==='content')filterAssets();if(state.page==='studio'){if(docCache)document.querySelector('#editable').innerHTML=docCache;countWords();}if(state.page==='analytics')mountAnalytics();mountBackend({icon,footer,esc,modal,toast},state.page);document.title=`${{home:'首页',studio:'AI 创作工作台',content:'内容中心',research:'研究',teardown:'视频拆解',capabilities:'功能与接口地图',settings:'设置',analytics:'数据中台'}[state.page]} · 鑫世界`}
function captureDoc(){const editor=document.querySelector('#editable');if(editor)docCache=editor.innerHTML;const prompt=document.querySelector('#prompt');if(prompt)state.draft=prompt.value}
function route(){const p=location.hash.slice(1).split('?')[0].split('/')[0];state.page=Object.hasOwn(pageRenderers,p)?p:'home';render();window.scrollTo(0,0)}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3000)}
function modal(title,body,actions=''){const d=document.querySelector('#dialog');d.innerHTML=`<div class="dialog-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></div>${body}${actions?`<div class="dialog-footer">${actions}</div>`:''}`;d.showModal()}
function newProject(){modal('让新想法，从这里开始。','<p class="dialog-copy">创建一个项目，开始与你的 AI 持续协作。项目仅保存在此浏览器原型中。</p><form id="project-form"><label class="field">项目名称<input name="name" required maxlength="60" placeholder="例如：秋日品牌企划" autofocus></label><label class="field">从一个想法开始<textarea name="idea" rows="3" placeholder="你想探索什么？（可选）" maxlength="2000"></textarea></label><div class="dialog-footer"><button type="button" class="btn" data-action="close">取消</button><button class="btn primary" type="submit">创建并开始 '+icon('arrow')+'</button></div></form>')}
function detail(id){const a=assets.find(x=>x.id===id);if(!a)return;modal(esc(a.title),`<img class="detail-image" src="assets/${a.img}" alt="${esc(a.title)}封面"><div class="detail-meta"><span class="badge">${a.kind}</span><span class="badge ${a.status==='已保存'?'green':'orange'}">${a.status}</span><span class="badge">项目：${a.project}</span></div><p class="detail-description">${a.type==='成果'?'这份示例成果来自项目中的持续协作。可以返回项目查看上下文，继续修改和保存。':'这是一份项目参考资料的展示示例。原型仅展示资料与项目关系，不执行正式解析或研究。'}</p>${a.id==='a1'&&state.saved?`<div class="detail-text">${esc(storage.get('documentText',''))}</div>`:''}`,`<button class="btn" data-action="close">关闭</button><button class="btn primary" data-action="open-project" data-name="${esc(a.project)}">回到项目 ${icon('arrow')}</button>`)}
function attach(start=false){const input=document.createElement('input');input.type='file';input.multiple=true;input.onchange=()=>{const names=[...input.files].map(f=>f.name);state.attachments.push(...names);if(start){state.draft=`请协助我整理这些资料：${names.join('、')}`;location.hash='studio';if(state.page==='studio')render()}else{document.querySelector('#attachments').innerHTML=attachmentRows();document.querySelector('#chat-attachments').textContent=state.attachments.join(' · ')}toast(`已附加 ${names.length} 个文件名称（未上传、未读取内容）`)};input.click()}
function save(){captureDoc();const text=document.querySelector('#editable')?.innerText||'';const ok=storage.set('document',docCache)&&storage.set('documentText',text)&&storage.set('saved',true);state.saved=ok;document.querySelector('#save-status').textContent=ok?'已保存到此浏览器':'无法写入本地存储';toast(ok?'成果已保存到此浏览器':'浏览器存储不可用，请导出成果保留修改')}
function countWords(){const e=document.querySelector('#editable');if(e)document.querySelector('#word-count').textContent=`${e.innerText.replace(/\s/g,'').length} 字 · 可直接编辑`}
function exportDoc(){const text=document.querySelector('#editable')?.innerText||storage.get('documentText','');const url=URL.createObjectURL(new Blob([`# ${state.project}\n\n${text}\n\n---\n鑫世界 Dual Experience 原型 · 示例文稿`],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='向新而行-品牌叙事.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('成果已导出为 Markdown 文件')}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.dataset.themeChoice){captureDoc();const chosen=t.dataset.themeChoice;document.documentElement.dataset.theme=chosen;try{localStorage.setItem('xinworld.prototype.theme',chosen)}catch{}const u=new URL(location.href);u.searchParams.set('theme',chosen);history.replaceState(null,'',u);document.querySelectorAll('[data-theme-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themeChoice===chosen)));return}if(t.dataset.project){state.project=t.dataset.project;storage.set('project',state.project);if(state.page==='studio')render()}if(t.dataset.favorite){const id=t.dataset.favorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];storage.set('favorites',state.favorites);t.setAttribute('aria-pressed',String(state.favorites.includes(id)));if(state.page==='content'){filterAssets();document.querySelector('[data-tab="收藏"] small').textContent=assets.filter(a=>state.favorites.includes(a.id)).length}return}if(t.dataset.detail){e.preventDefault();detail(t.dataset.detail);return}if(t.dataset.tab){state.tab=t.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tab===state.tab)));filterAssets();return}if(t.dataset.view){state.view=t.dataset.view;document.querySelector('#assets').classList.toggle('list',state.view==='list');document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===state.view)));return}if(t.dataset.panel){state.panel=t.dataset.panel;document.querySelector('.studio').dataset.panel=state.panel;document.querySelectorAll('[data-panel].btn').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.panel===state.panel)));return}if(t.dataset.prompt){document.querySelector('#prompt').value=t.dataset.prompt;state.draft=t.dataset.prompt;document.querySelector('#prompt').focus();return}switch(t.dataset.action){case'open-settings':location.hash='settings';break;case'new':newProject();break;case'close':document.querySelector('#dialog').close();break;case'start':state.draft='';location.hash='studio';break;case'import':attach(true);break;case'attach':attach();break;case'save':save();break;case'export':exportDoc();break;case'focus-chat':state.panel='chat';document.querySelector('.studio').dataset.panel='chat';document.querySelector('#prompt').focus();break;case'focus-doc':state.panel='document';document.querySelector('.studio').dataset.panel='document';document.querySelectorAll('[data-panel].btn').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.panel==='document')));document.querySelector('#editable').focus();break;case'skill':state.skills=state.skills.length?[]:['品牌叙事'];document.querySelector('#skill-label').textContent=state.skills.length?'品牌叙事 · 已启用':'添加专业技能';document.querySelector('#skill-count').textContent=state.skills.length;toast(state.skills.length?'已选择品牌叙事技能（演示）':'已移除技能，仍可继续通用对话');break;case'open-project':state.project=t.dataset.name+' · 项目';storage.set('project',state.project);document.querySelector('#dialog').close();location.hash='studio';if(state.page==='studio')render();break;case'brief':modal('品牌背景与目标','<p class="detail-description">品牌：鑫世界 XIN WORLD<br>定位：以项目为长期工作容器的通用 AI 工作台。<br>视觉线索：红色圆点、三条水平弧线、中性灰。<br>本次目标：让品牌叙事简洁、有力量，也保留温度。<br><br>这是原型参考文本，不是新增产品规则。</p>');break;case'notifications':modal('消息','<p class="dialog-copy">目前没有新消息。这里为独立原型，不读取正式通知。</p>');break;case'account':modal('本地演示工作空间','<p class="dialog-copy">当前为无登录的独立 UI 原型。示例数据不代表真实用户、项目、权限或工作空间。</p>');break;case'clear-filter':state.tab='全部';state.search='';state.status='全部状态';render();break;case'projects':modal('我的项目',`<div style="display:grid;gap:10px">${[...state.customProjects,...projects].map(p=>`<button class="btn" data-action="open-project" data-name="${esc(p.title)}">${icon('folder')}${esc(p.title)}${icon('arrow')}</button>`).join('')}</div>`);break;case'search':modal('找到你的创作','<label class="field">搜索项目与内容<input id="global-search" placeholder="输入关键词…" autofocus></label><div id="global-results" style="display:grid;gap:8px;margin-top:18px"></div>');globalSearch('');break;case'font-smaller':case'font-larger':{const editor=document.querySelector('#editable');const size=Number(editor.dataset.size||12)+(t.dataset.action==='font-larger'?1:-1);editor.dataset.size=Math.min(20,Math.max(10,size));editor.querySelectorAll('p').forEach(p=>p.style.fontSize=editor.dataset.size+'px');break}case'spec':modal('Dual Experience · 设计系统','<p class="dialog-copy">同一功能架构，两种创作体验。</p><div class="spec-swatches"><span style="background:var(--bg)">背景</span><span style="background:var(--surface)">表面</span><span style="background:var(--surface-2)">浮层</span><span style="background:#c53532;color:#fff">品牌红</span></div><p class="spec-list">Dark Studio：中性黑灰、64px 图标导航、精细边界、专业密度。<br>Light Edition：白与浅灰、强排版层级、简洁 Hero、大幅成果展示。<br>两套主题共享组件，使用颜色与密度 Tokens；红色圆点与水平弧线贯穿品牌。</p>', '<a class="btn primary" href="DESIGN-SPEC.md" target="_blank">完整设计规范 ↗</a>');break;case'help':modal('原型使用说明','<p class="spec-list">顶部可真实切换主题，偏好保存在浏览器。<br>首页支持创建本地示例项目，项目卡片可进入创作工作区。<br>创作页支持示例对话、可选技能、文稿编辑、保存和导出。<br>内容中心支持搜索、类型与状态筛选、收藏、详情和列表视图。<br>手机可在对话与成果编辑面板间切换。<br><br>所有数据仅用于交互演示，未连接正式 API。资料附加只保留名称。</p>');break}});
function globalSearch(value){const results=[...state.customProjects,...projects].filter(p=>p.title.includes(value));const found=assets.filter(a=>a.title.includes(value));document.querySelector('#global-results').innerHTML=results.map(p=>`<button class="btn" data-action="open-project" data-name="${esc(p.title)}">${icon('folder')}${esc(p.title)}</button>`).join('')+found.map(a=>`<button class="btn" data-detail="${a.id}">${icon('file')}${a.title}</button>`).join('')||'<p class="dialog-copy">没有匹配的项目或内容。</p>'}
document.addEventListener('input',e=>{if(e.target.id==='content-search'){state.search=e.target.value;filterAssets()}if(e.target.id==='global-search')globalSearch(e.target.value);if(e.target.closest('#editable')){state.saved=false;document.querySelector('#save-status').textContent='尚未保存修改';countWords()}if(e.target.id==='prompt'){state.draft=e.target.value;storage.set('draft',state.draft)}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){state.status=e.target.value;filterAssets()}});
document.addEventListener('submit',async e=>{if(e.target.id==='project-form'){e.preventDefault();const f=new FormData(e.target);state.project=String(f.get('name')).trim();if(!state.project)return;state.draft=String(f.get('idea')).trim();const p={...projects[0],id:'local-'+Date.now(),title:state.project,date:'刚刚',count:0,status:'进行中'};state.customProjects.unshift(p);storage.set('projects',state.customProjects);storage.set('project',state.project);storage.set('draft',state.draft);document.querySelector('#dialog').close();location.hash='studio';if(state.page==='studio')render();toast('已创建本地示例项目')}if(e.target.id==='chat-form'){e.preventDefault();const text=document.querySelector('#prompt').value.trim();if(!text||working)return;working=true;state.messages.push({role:'user',text});document.querySelector('#chat-thread').insertAdjacentHTML('beforeend',userMsg(text));state.draft='';document.querySelector('#prompt').value='';storage.set('draft','');document.querySelector('.send').disabled=true;await new Promise(r=>setTimeout(r,650));let reply=text.includes('标题')?'三个标题方向供你选择：① 向新而行，让想法有回响。② 从一束灵感，到一个新世界。③ 好想法，值得被实现。':text.includes('100')?'精简版示例：鑫世界，让好想法成为作品。以项目连接资料、对话与成果，与你持续探索、修改和积累。从一个问题出发，越过想象的地平线，抵达属于你的新世界。':'可以从「世界的下一种可能，始于你的一个想法」切入，让开头更直接。你可以把这句加入成果区继续打磨。这是固定演示回复，未调用 AI 服务。';state.messages.push({role:'ai',text:reply});if(state.page==='studio'){document.querySelector('#chat-thread').insertAdjacentHTML('beforeend',aiMsg(reply));document.querySelector('.send').disabled=false}working=false;toast('演示回复已完成，文稿可在成果区继续编辑')}});
document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
document.addEventListener('teardown-handoff',e=>{state.project=e.detail.title;storage.set('project',state.project)});window.addEventListener('hashchange',route);window.addEventListener('beforeunload',()=>storage.set('draft',state.draft));route();
